                        a *= 1 * h;
                        FT[1 * nb + b] = inr ? taylor(f + 1, dt) : a;
                        a *= 3 * h;
                        FT[2 * nb + b] = inr ? taylor(f + 2, dt) : a;
                        a *= 5 * h;
                        FT[3 * nb + b] = inr ? taylor(f + 3, dt) : a;
                        a *= 7 * h;
                        FT[4 * nb + b] = inr ? taylor(f + 4, dt) : a;
                        a *= 9 * h;
                        FT[5 * nb + b] = inr ? taylor(f + 5, dt) : a;
